    def rancher(self) -> RancherCollection:
        return RancherCollection(self._session)

    @cached_property
    def registries(self) -> RegistryCollection:
        return RegistryCollection(self._session)

    async def get_managed_kubernetes(
        self,
        *,
        project: str | None = None,
    ) -> list[_PublicCloudV2PublicCloudManagedKubernetesCluster]:
        """
        GET /v2/publicCloud/project/{projectId}/managedKubernetes

        List managed Kubernetes clusters.

        API status: BETA.
        """
        return await self._session.api(
            _PublicCloudV2API
        ).list_project_managed_kubernetes(
            project_id=_scoped(
                {"project": project},
                "project",
                self._session.client.settings.default_project,
            )
        )

    async def submit_managed_kubernetes(
        self,
        *,
        project: str | None = None,
        body: PublicCloudManagedKubernetesClusterCreation,
    ) -> PublicCloudItem:
        """
        POST /v2/publicCloud/project/{projectId}/managedKubernetes

        Create a managed Kubernetes cluster.

        API status: BETA.
        """
        return PublicCloudItem._from(
            self._session,
            {},
            await self._session.api(
                _PublicCloudV2API
            ).create_project_managed_kubernetes(
                project_id=_scoped(
                    {"project": project},
                    "project",
                    self._session.client.settings.default_project,
                ),
                body=body,
            ),
        )
